import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.D8u9WiMi.js";const c="/SumUP/assets/69465cf9e1fd8e60edb89283b6f8d92d.BLcSoKsk.png",i="/SumUP/assets/e895b0c6ed06357d1e49ae572157caa7.BibHC6PU.png",d="/SumUP/assets/5e16b16cf848691116950ef6a8979e98.CfssHXa8.png",g=JSON.parse('{"title":"知识加油站","description":"","frontmatter":{},"headers":[],"relativePath":"server/java/basic/primary/supplement.md","filePath":"server/java/basic/primary/supplement.md"}'),s={name:"server/java/basic/primary/supplement.md"};function n(l,e,p,h,m,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="知识加油站" tabindex="-1">知识加油站 <a class="header-anchor" href="#知识加油站" aria-label="Permalink to &quot;知识加油站&quot;">​</a></h1><h2 id="java内存模型" tabindex="-1">Java内存模型 <a class="header-anchor" href="#java内存模型" aria-label="Permalink to &quot;Java内存模型&quot;">​</a></h2><p>在Java中，执行一个<code>helloWorld</code>方法的内存图</p><p><img src="'+c+'" alt="image-20230303093525909"></p><blockquote><p><strong>栈内存</strong>为方法提供使用、<strong>堆内存</strong>为对象提供使用、方法区为执行的class文件临时存储</p></blockquote><div class="tip custom-block"><p class="custom-block-title">提示</p><ul><li>参考资料：<a href="https://www.bilibili.com/video/BV17F411T7Ao/?p=107" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV17F411T7Ao/?p=107</a></li><li>当执行main方法时，会生成StringDemo这个class文件</li></ul></div><h2 id="idea快捷键" tabindex="-1">Idea快捷键 <a class="header-anchor" href="#idea快捷键" aria-label="Permalink to &quot;Idea快捷键&quot;">​</a></h2><h3 id="查看接口实现类" tabindex="-1">查看接口实现类 <a class="header-anchor" href="#查看接口实现类" aria-label="Permalink to &quot;查看接口实现类&quot;">​</a></h3><blockquote><p>Ctrl+Alt+B</p></blockquote><p>选中一个方法，按键Ctrl+Alt+B即可查看实现此接口的实现类</p><p><img src="'+i+'" alt="image-20230321143750637"></p><h3 id="图标小细节" tabindex="-1">图标小细节 <a class="header-anchor" href="#图标小细节" aria-label="Permalink to &quot;图标小细节&quot;">​</a></h3><p>Ctrl+F12可以查看当前类中的状态，例如成员方法，成员属性等等</p><p><img src="'+d+'" alt="image-20230424201934606"></p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>C表示类，M表示方法，F表示常量或，静态成员变量，-&gt;表示继承，T表示重写</p></div><h2 id="int和integer的区别" tabindex="-1">int和Integer的区别 <a class="header-anchor" href="#int和integer的区别" aria-label="Permalink to &quot;int和Integer的区别&quot;">​</a></h2><p>在Java中，<code>int</code>是一种原始数据类型，用于表示整数值。它是Java中最常用的数据类型之一，他的大小为4个字节（32位），可以表示介于-2,147,483,648和2,147,483,647之间的整数。</p><p>而<code>Integer</code>是Java中的一个类，他封装了一个基本类型的int值。他允许将int值作为参数传递给需要一个对象的方法，也可以将int值转换为其他类型的值，例如字符串。</p><p>因此，<code>int</code>和<code>Integer</code>的主要区别在于<code>int</code>是个原始数据类型，<code>Integer</code>是个类，用于封装<code>int</code>值以便进行更多操作。此外，<code>int</code>在Java中是基本数据类型，而<code>Integer</code>是引用数据类型，也就是说其实<code>Integer</code>其实是个引用的指针，不是个简单的数据值。</p><h2 id="string和character区别" tabindex="-1">String和Character区别 <a class="header-anchor" href="#string和character区别" aria-label="Permalink to &quot;String和Character区别&quot;">​</a></h2><p><code>String</code>是一种对象，用于表示一组字符序列(就是字符串)，它是Java中的一个类，具有很多使用方法来处理字符串，例如连接、替换、分割和查找，字符串常量一般用双引号引起来，如：<code>&quot;你好啊，李银河&quot;</code></p><p><code>Character</code>是Java中char类型的包装类，他用于表示单个字符每个<code>Character</code>对象都包含一个<code>char</code>类型的值。他也具有一些实用的方法来操作和处理字符。如字符的大小写转换等。字符常来通常可以用单引号引起来，如：<code>&#39;A&#39;</code>。</p><p>因此，<code>String</code>和<code>Character</code>的主要区别在于他们表示的数据类型不一样。<code>String</code>表示一组字符，而<code>Character</code>表示单个字符。此外<code>String</code>是个类，而<code>Character</code>是个简单的数据类型。在Java中，字符串是不可变的，因此不能再原始字符串上更改，而<code>Character</code>是可以变的，因为他只表示一个字符。</p>',23)])])}const _=a(s,[["render",n]]);export{g as __pageData,_ as default};
